declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/ai.php';$u=require_user($pdo);$id=(string)($_GET['id']??$_POST['id']??'');$project=project_access($pdo,(int)$u['id'],$id);if(!$project){http_response_code(404);exit('Research project not found.');}$canWrite=project_can_write($project);$success='';$error='';$aiAnswer='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$op=(string)($_POST['op']??'');try{
 if(!$canWrite)throw new RuntimeException('You have view-only access to this project.');
 if($op==='add_source'){$url=trim((string)($_POST['url']??''));if(!filter_var($url,FILTER_VALIDATE_URL))throw new RuntimeException('Enter a valid source URL.');$s=ensure_source($pdo,$url,trim((string)($_POST['title']??''))?:null);$pdo->prepare('INSERT IGNORE INTO project_sources(project_id,source_id,added_by_user_id) VALUES(?,?,?)')->execute([$project['id'],$s['id'],$u['id']]);$pdo->prepare("INSERT INTO source_monitor_jobs(source_id,priority,status) SELECT ?,3,'queued' WHERE NOT EXISTS(SELECT 1 FROM source_monitor_jobs WHERE source_id=? AND status IN ('queued','processing'))")->execute([$s['id'],$s['id']]);$success='Source added and queued for integrity capture.';}
 if($op==='note'){$body=trim((string)($_POST['body']??''));if($body==='')throw new RuntimeException('Note cannot be empty.');$pdo->prepare('INSERT INTO research_notes(public_id,project_id,user_id,body) VALUES(?,?,?,?)')->execute([ulid_like(),$project['id'],$u['id'],$body]);$success='Research note added.';}
 if($op==='task'){$title=trim((string)($_POST['title']??''));if($title==='')throw new RuntimeException('Task title is required.');$type=in_array($_POST['task_type']??'general',['general','find_source','verify_claim','review_source_change'],true)?$_POST['task_type']:'general';$pdo->prepare('INSERT INTO research_tasks(public_id,project_id,created_by_user_id,title,description,task_type) VALUES(?,?,?,?,?,?)')->execute([ulid_like(),$project['id'],$u['id'],$title,trim((string)($_POST['description']??''))?:null,$type]);$success='Research task added.';}
 if($op==='task_status'){$task=(string)($_POST['task']??'');$status=in_array($_POST['status']??'open',['open','in_progress','done','archived'],true)?$_POST['status']:'open';$pdo->prepare('UPDATE research_tasks SET status=? WHERE public_id=? AND project_id=?')->execute([$status,$task,$project['id']]);$success='Task updated.';}
 if($op==='ask_ai'){
   if(!user_is_pro($pdo,$u))throw new RuntimeException('Ask Annotated is available to Pro users.');$question=trim((string)($_POST['question']??''));if($question==='')throw new RuntimeException('Ask a research question.');$model=ai_setting_model_id($pdo,'research',true);if(!$model)$model=ai_setting_model_id($pdo,'pro',true);if(!$model)throw new RuntimeException('No Pro research model is configured.');$mr=ai_model_record($pdo,$model);if(($u['role']??'')!=='admin'&&!(int)$mr['pro_enabled'])throw new RuntimeException('The configured research model is not enabled for Pro users.');$ctx=ai_research_context($pdo,(int)$project['id']);$system='You are Ask Annotated, a provenance-first research assistant. Use only the supplied project context. Separate source evidence from inference. Cite exact IDs like [SOURCE id] and [ANNOTATION id]. If the context cannot answer the question, say what evidence is missing. Never invent citations.';$prompt="Project: {$project['title']}\nQuestion: {$question}\n\nPROJECT CONTEXT:\n".$ctx['text'];$r=ai_run($pdo,$config,$u,($u['role']??'')==='admin'?'admin':'pro','research_question',$model,$system,$prompt,array_merge($ctx['refs'],[['type'=>'question','text'=>$question]]),'research_project',$project['public_id']);$aiAnswer=$r['text'];
 }
}catch(Throwable $e){$error=$e->getMessage();}}
$q=$pdo->prepare('SELECT s.public_id,s.title,s.canonical_url,s.domain,s.status,s.last_checked_at,ps.created_at FROM project_sources ps JOIN sources s ON s.id=ps.source_id WHERE ps.project_id=? ORDER BY ps.created_at DESC');$q->execute([$project['id']]);$sources=$q->fetchAll();$q=$pdo->prepare("SELECT a.public_id,a.text_commentary,a.published_at,u2.display_name,s.title source_title,s.public_id source_public_id FROM project_annotations pa JOIN annotations a ON a.id=pa.annotation_id JOIN users u2 ON u2.id=a.user_id JOIN sources s ON s.id=a.source_id WHERE pa.project_id=? ORDER BY pa.created_at DESC");$q->execute([$project['id']]);$annotations=$q->fetchAll();$q=$pdo->prepare('SELECT rn.*,u2.display_name FROM research_notes rn JOIN users u2 ON u2.id=rn.user_id WHERE rn.project_id=? ORDER BY rn.created_at DESC');$q->execute([$project['id']]);$notes=$q->fetchAll();$q=$pdo->prepare('SELECT * FROM research_tasks WHERE project_id=? ORDER BY FIELD(status,\'open\',\'in_progress\',\'done\',\'archived\'),created_at DESC');$q->execute([$project['id']]);$tasks=$q->fetchAll();$q=$pdo->prepare("SELECT output_text,created_at FROM ai_runs WHERE scope_type='research_project' AND scope_public_id=? AND status='completed' ORDER BY created_at DESC LIMIT 5");$q->execute([$project['public_id']]);$aiRuns=$q->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($project['title'])?> · Research · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/home.php">Annotated</a><nav><a href="/research.php">Research</a><a href="/search.php">Search</a><a href="/saved.php">Saved</a><?php if(user_is_pro($pdo,$u)):?><a href="/ai.php">AI</a><?php endif?></nav></header><main class="layout"><section><div class="pageTitle"><span class="eyebrow">RESEARCH PROJECT · <?=h(strtoupper($project['access_role']))?></span><h1><?=h($project['title'])?></h1><p><?=nl2br(h($project['description']))?></p></div><?php if($success):?><div class="success"><?=h($success)?></div><?php endif?><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?><?php if($aiAnswer):?><div class="card aiAnswer"><span class="eyebrow">ASK ANNOTATED</span><p><?=nl2br(h($aiAnswer))?></p></div><?php endif?><h2>Sources</h2><?php if(!$sources):?><div class="card empty">No sources yet.</div><?php endif?><?php foreach($sources as $s):?><article class="card"><div class="meta"><?=h($s['domain'])?> · <?=h($s['status'])?> · checked <?=h($s['last_checked_at']?:'pending')?></div><h3><a href="/source.php?id=<?=h($s['public_id'])?>"><?=h($s['title']?:$s['canonical_url'])?></a></h3><a href="<?=h($s['canonical_url'])?>" target="_blank" rel="noopener">Original source ↗</a></article><?php endforeach?><h2>Annotations</h2><?php foreach($annotations as $a):?><article class="card"><div class="meta"><?=h($a['display_name'])?> · <?=h($a['published_at'])?></div><h3><?=h($a['source_title'])?></h3><p><?=nl2br(h($a['text_commentary']))?></p><a href="/annotation.php?id=<?=h($a['public_id'])?>">Open annotation</a></article><?php endforeach?><h2>Notes</h2><?php foreach($notes as $n):?><article class="card"><div class="meta"><?=h($n['display_name'])?> · <?=h($n['created_at'])?></div><p><?=nl2br(h($n['body']))?></p></article><?php endforeach?><h2>Tasks</h2><?php foreach($tasks as $t):?><article class="card"><div class="meta"><?=h($t['task_type'])?> · <?=h($t['status'])?></div><h3><?=h($t['title'])?></h3><p><?=nl2br(h($t['description']))?></p><?php if($canWrite):?><form method="post" class="inlineForm"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($project['public_id'])?>"><input type="hidden" name="op" value="task_status"><input type="hidden" name="task" value="<?=h($t['public_id'])?>"><select name="status"><?php foreach(['open','in_progress','done','archived'] as $st):?><option <?=$t['status']===$st?'selected':''?>><?=$st?></option><?php endforeach?></select><button>Update</button></form><?php endif?></article><?php endforeach?><?php if($aiRuns):?><h2>Recent AI research</h2><?php foreach($aiRuns as $r):?><details class="card"><summary><?=h($r['created_at'])?></summary><p><?=nl2br(h($r['output_text']))?></p></details><?php endforeach?><?php endif?></section><aside><?php if($canWrite):?><div class="card"><h3>Add source</h3><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($project['public_id'])?>"><input type="hidden" name="op" value="add_source"><label>URL<input type="url" name="url" required></label><label>Title (optional)<input name="title"></label><button>Add source</button></form></div><div class="card"><h3>Add note</h3><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($project['public_id'])?>"><input type="hidden" name="op" value="note"><textarea name="body" rows="5" required></textarea><button>Add note</button></form></div><div class="card"><h3>Add task</h3><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($project['public_id'])?>"><input type="hidden" name="op" value="task"><input name="title" required placeholder="What needs to be researched?"><select name="task_type"><option value="general">General</option><option value="find_source">Find source</option><option value="verify_claim">Verify claim</option><option value="review_source_change">Review source change</option></select><textarea name="description" rows="3"></textarea><button>Add task</button></form></div><?php endif?><div class="card"><h3>Ask Annotated</h3><?php if($canWrite&&user_is_pro($pdo,$u)):?><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($project['public_id'])?>"><input type="hidden" name="op" value="ask_ai"><textarea name="question" rows="5" required placeholder="What does the evidence say about…?"></textarea><button>Ask project AI</button></form><?php else:?><p class="meta">Available on Pro. Your project data remains permission-scoped and every answer keeps source/annotation references.</p><?php endif?></div></aside></main></body></html>